package com.careflow.hospital.scheduling;
import com.careflow.hospital.audit.AuditService;import com.careflow.hospital.doctors.*;import com.careflow.hospital.shared.DomainException;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class DoctorScheduleServiceTest {DoctorRepository doctors=mock(DoctorRepository.class);DoctorScheduleRepository schedules=mock(DoctorScheduleRepository.class);DoctorScheduleExceptionRepository exceptions=mock(DoctorScheduleExceptionRepository.class);AuditService audit=mock(AuditService.class);DoctorScheduleService service;UUID userId=UUID.randomUUID(),doctorId=UUID.randomUUID();Doctor doctor=mock(Doctor.class);@BeforeEach void setup(){service=new DoctorScheduleService(doctors,schedules,exceptions,audit);when(doctor.getId()).thenReturn(doctorId);when(doctor.isActive()).thenReturn(true);when(doctors.findByUserId(userId)).thenReturn(Optional.of(doctor));when(schedules.save(any())).thenAnswer(i->i.getArgument(0));when(exceptions.save(any())).thenAnswer(i->i.getArgument(0));}
 @Test void createsNonOverlappingAvailability(){var view=service.createSchedule(userId,new ScheduleDtos.CreateSchedule(1,LocalTime.of(9,0),LocalTime.of(12,0),30));assertEquals(30,view.slotDurationMinutes());verify(audit).record(eq(userId),eq("DOCTOR_SCHEDULE_CREATED"),eq("DOCTOR_SCHEDULE"),any(),eq("SUCCESS"));}
 @Test void rejectsOverlappingAvailability(){var existing=new DoctorSchedule(doctorId,1,LocalTime.of(9,0),LocalTime.of(12,0),30);when(schedules.findAllByDoctorIdAndDayOfWeekAndActiveTrue(any(),eq(1))).thenReturn(List.of(existing));assertThrows(DomainException.class,()->service.createSchedule(userId,new ScheduleDtos.CreateSchedule(1,LocalTime.of(11,0),LocalTime.of(13,0),30)));verify(schedules,never()).save(any());}
 @Test void availableExceptionRequiresTimes(){assertThrows(DomainException.class,()->service.createException(userId,new ScheduleDtos.CreateException(LocalDate.now().plusDays(1),"AVAILABLE",null,null,30,"Extra clinic")));}
}
